COL=['#0072BD','#D95319','#EDB120','#7E2F8E','#77AC30','#4DBEEE']
AUDIT=[]
def rows(key):return list(csv.DictReader(io.StringIO(DATA[key])))
def canvas(stacked=False,legend_rows=1):
    height=(3.82 if stacked else 2.08)+(legend_rows-1)*.15
    fig=plt.figure(figsize=(3.5,height))
    if stacked:
        axes=[fig.add_axes([.50/3.5,y/height,2.90/3.5,1.25/height]) for y in [2.10,.40]]
    else:axes=[fig.add_axes([.50/3.5,.40/height,2.90/3.5,1.30/height])]
    return fig,axes

def axis(ax,rr,snr=True):
    vals=[max(int(r['bit_errors']),1)/int(r['bits']) for r in rr]
    lo=min(vals+[2e-4])*.65
    ax.set(yscale='log',ylim=(lo,min(1,max(vals)*2.5)),ylabel='BER',xlabel=r'$E_b/N_0$ (dB)' if snr else 'Total iteration')
    if snr:ax.set(xlim=(3.8,18.2),xticks=range(4,19,2))
    ax.yaxis.set_major_locator(LogLocator(base=10,numticks=5));ax.yaxis.set_minor_locator(NullLocator())
    ax.tick_params(direction='in',pad=2);ax.grid(which='major',axis='both',color='#D5D8DC',lw=.5);ax.set_axisbelow(True)
    ax.axhline(2e-4,color='#5D6D7E',ls=(0,(3,3)),lw=.9)
    ax.text(.02,2e-4*1.2,r'$2\times10^{-4}$',transform=ax.get_yaxis_transform(),ha='left',va='bottom',fontsize=9,color='black')

def draw(ax,rr,label,color,marker,ls='-',offset=0,period=3,xkey='snr'):
    rr=sorted(rr,key=lambda r:float(r[xkey]));x=np.array([float(r[xkey]) for r in rr]);errors=np.array([int(r['bit_errors']) for r in rr]);bits=np.array([int(r['bits']) for r in rr]);raw=errors/bits
    assert all(np.isclose(float(r['ber']),v,rtol=1e-12,atol=1e-15) for r,v in zip(rr,raw))
    y=np.maximum(errors,1)/bits
    ax.plot(x,y,color=color,ls=ls,lw=2,label=label)
    idx=np.arange(len(x))[np.arange(len(x))%period==offset]
    positive=idx[errors[idx]>0];zero=idx[errors[idx]==0]
    ax.plot(x[positive],y[positive],ls='none',marker=marker,ms=4.5,mfc='white',mec=color,mew=1,zorder=10)
    ax.plot(x[zero],y[zero],ls='none',marker='v',ms=4.5,mfc='white',mec=color,mew=1,zorder=10)
    AUDIT.append(dict(series=label,x=x.tolist(),bit_errors=errors.tolist(),bits=bits.tolist(),display=y.tolist()))
    return Line2D([],[],color=color,ls=ls,lw=2,marker=marker,ms=4.5,mfc='white',mec=color,label=label)

def legend(fig,handles,ncol):
    fig.legend(handles=handles,ncol=ncol,loc='upper center',bbox_to_anchor=(.54,.995),frameon=False,fontsize=10,handlelength=1.45,handletextpad=.3,columnspacing=.6,labelspacing=.2,borderaxespad=0)

def matrix_legend(fig,groups,row_names,columns):
    handles=[Line2D([],[],ls='none',label=n) for n in row_names];labels=row_names.copy()
    for j,col in enumerate(columns):
        for i in range(2):handles.append(groups[i][j]);labels.append(col)
    leg=fig.legend(handles,labels,ncols=4,loc='upper center',bbox_to_anchor=(.5,.995),frameon=False,fontsize=10,handlelength=1.35,handletextpad=.22,columnspacing=.45,labelspacing=.2,borderaxespad=0)
    for row in leg._legend_handle_box.get_children()[0].get_children():row.get_children()[0].set_width(0);row.sep=0

def save(fig,name):
    # Pack the outside legend just above the frames/titles at the final physical size.
    fig.canvas.draw();renderer=fig.canvas.get_renderer();height=fig.get_figheight()
    positions=[a.get_position().frozen() for a in fig.axes]
    top=max(pos.y1*height for pos in positions)
    for ax in fig.axes:
        if ax.get_title():top=max(top,ax.title.get_window_extent(renderer).y1/fig.dpi)
    leg=fig.legends[0];legend_height=leg.get_window_extent(renderer).height/fig.dpi
    lower=top+2/72;new_height=lower+legend_height+1.5/72
    fig.set_size_inches(fig.get_figwidth(),new_height,forward=True)
    for ax,pos in zip(fig.axes,positions):ax.set_position([pos.x0,pos.y0*height/new_height,pos.width,pos.height*height/new_height])
    leg.set_bbox_to_anchor((.5,lower/new_height),transform=fig.transFigure);leg._loc=8
    for ext in ['pdf','png','svg']:_save(fig,OUT/(name+'.'+ext),dpi=300,transparent=True,facecolor='none',edgecolor='none')
    plt.close(fig)

# S2: matched six-iteration batch-size diagnostic.
rr=rows('batch_sizes');fig,aa=canvas();ax=aa[0];axis(ax,rr,False);hh=[]
for b,color,mk,ls in [(16,COL[3],'^','-.'),(32,COL[0],'o','-'),(64,COL[1],'s','--')]:hh.append(draw(ax,[r for r in rr if int(r['batch_size'])==b],f'Batch {b}',color,mk,ls,period=1,xkey='total_iteration'))
