# Complete RT supplement: all seven city/position/direction conditions and three delays.
def rt_grid(panels,name):
    nrows=(len(panels)+1)//2
    height=nrows*1.92+.24
    fig=plt.figure(figsize=(7.16,height));hh=[]
    for k,(key,field,value,title) in enumerate(panels):
        row,col=divmod(k,2)
        ax=fig.add_axes([(.50+3.62*col)/7.16,(.40+(nrows-1-row)*1.92)/height,2.90/7.16,1.18/height])
        selected=[r for r in rows(key) if str(r[field])==str(value)]
        axis(ax,selected);ax.set_title(f'({chr(97+k)}) {title}',fontsize=10,pad=5);hh=[]
        for j,m in enumerate(['FastSET','CNN']):
            for phaseidx,phase in enumerate(['pretrained','adapted']):
                hh.append(draw(ax,[r for r in selected if r['method']==m and r['phase']==phase],['FastSET','E2E'][j]+(' before' if phaseidx==0 else ' after'),COL[j],['o','s'][j],(0,(3,1.8)) if phaseidx==0 else '-',offset=2*j+phaseidx,period=4,xkey='snr_db'))
    legend(fig,hh,4);save(fig,name)
rt_grid([('rt_curves','case',c,t) for c,t in [('Paris P2','Paris P1'),('Munich P2','Munich P1'),('Florence P2','Florence P1'),('San Francisco P2','San Francisco P1')]],'rt_cities_fullrange')
rt_grid([('rt_curves','case',c,t) for c,t in [('Paris P3','Paris P2'),('Paris to San Francisco','Paris to San Francisco'),('San Francisco to Paris','San Francisco to Paris')]]+[('rt_delay_curves','delay_ns',d,f'Paris P1, {d} ns') for d in [600,900,1200]],'rt_positions_delay_fullrange')

